sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float blockSize;

half4 main(float2 coord) {
    float2 block = floor(coord.xy / blockSize);
    float2 sampleCoord = block * blockSize;
    half4 color = image.eval(sampleCoord);
    if (color.a < 0.001) {
        return half4(0);
    }
    color.rgb /= color.a;
    color.rgb *= color.a;
    return color;
}
